from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector
from taf.rfrl.procedures.resources.python.status_check.exceptions import InvalidRATvariant


class Rat:

    _status_selector = StatusSelector()

    @classmethod
    def get_expected_statuses(cls, variant):
        """
        Returns expected values of statuses for given variant.
        Statuses are visible in the infomodel under the object: 'nr': 'NRBTS_M', 'lte': 'LNBTS_M', 'wcdma': 'WNBTS_M',
                                                                'gsm': 'GNBTS_M'
        :param variant: variant of expected statuses, can be one of: 'enabled', 'disabled', 'offline', 'degraded',
                                                                     'not_commissioned', 'dedicated_for_rat_reset'
        :type variant: str
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        :raises InvalidRATvariant: if provided RAT variant does not exist
        """
        status_methods = {
            'enabled': cls._get_enabled_statuses,
            'disabled': cls._get_disabled_statuses,
            'offline': cls._get_offline_statuses,
            'degraded': cls._get_degraded_statuses,
            'not_commissioned': cls._get_not_commissioned_statuses,
            'dedicated_for_rat_reset': cls._get_dedicated_for_rat_reset_statuses,
        }
        try:
            return status_methods[variant]()
        except KeyError:
            raise InvalidRATvariant(f"Provided RAT variant does not exist: {variant}")

    @classmethod
    def _get_enabled_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='enabled'),
                'availabilityStatus': 'online',
                'proceduralState': 'onair'}

    @classmethod
    def _get_disabled_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='failed'),
                'proceduralState': 'commissioned'}

    @classmethod
    def _get_offline_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled'),
                'availabilityStatus': 'offline',
                'proceduralState': 'commissioned'}

    @classmethod
    def _get_degraded_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='enabled'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='degraded'),
                'proceduralState': 'onair'}

    @classmethod
    def _get_not_commissioned_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='offline'),
                'proceduralState': 'notcommissioned'}

    @classmethod
    def _get_dedicated_for_rat_reset_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled').capitalize()}
